/**
 * BioChem — domain types & jsonb accessors.
 *
 * `database.ts` mirrors the live database (it is regenerated by the
 * "Database sync" GitHub workflow), so jsonb columns arrive typed as
 * the generic `Json`. This module gives every jsonb shape a real,
 * runtime-checked accessor and re-exports the schema types, so the
 * rest of the app imports everything from "@/types/domain".
 *
 * Accessors validate lazily and fall back to safe defaults — corrupt
 * data renders as an empty structure instead of crashing a page.
 */

import type { Database, Json } from "./database";

export type { Database, Json } from "./database";
export type { Tables, TablesInsert, TablesUpdate, Views, Enums, CompositeTypes } from "./database";

// ---------------------------------------------------------------------------
// Schema-derived unions
// ---------------------------------------------------------------------------

export type UserRole = Database["public"]["Enums"]["user_role"];
export type ExamZone = Database["public"]["Enums"]["exam_zone"];
export type Difficulty = Database["public"]["Enums"]["difficulty"];
export type ContentStatus = Database["public"]["Enums"]["content_status"];
export type QuestionType = Database["public"]["Enums"]["question_type"];
export type AttemptStatus = Database["public"]["Enums"]["attempt_status"];
export type AttemptMode = Database["public"]["Enums"]["attempt_mode"];
export type JobType = Database["public"]["Enums"]["job_type"];
export type JobStatus = Database["public"]["Enums"]["job_status"];
export type EnquiryStatus = Database["public"]["Enums"]["enquiry_status"];
export type AdPlacement = Database["public"]["Enums"]["ad_placement"];
export type NotificationType = Database["public"]["Enums"]["notification_type"];
export type SubmissionType = Database["public"]["Enums"]["submission_type"];
export type PlanEventType = Database["public"]["Enums"]["plan_event_type"];
export type AiTaskType = Database["public"]["Enums"]["ai_task_type"];
export type Visibility = Database["public"]["Enums"]["visibility"];
export type ChatReportStatus = Database["public"]["Enums"]["chat_report_status"];
export type AiQueueStatus = Database["public"]["Enums"]["ai_queue_status"];

/** Chat conversation kinds (text column with a check constraint). */
export type ChatConversationKind = "direct" | "group" | "lounge";
/** Chat message kinds — determines how the client renders/decrypts. */
export type ChatMessageKind = "text" | "image" | "video" | "audio" | "voice" | "file";
export type SupportCategory = "bug" | "complaint" | "question" | "feedback";
export type SupportStatus = "open" | "in_progress" | "resolved";

export function isChatConversationKind(value: string): value is ChatConversationKind {
  return value === "direct" || value === "group" || value === "lounge";
}

export function isChatMessageKind(value: string): value is ChatMessageKind {
  return ["text", "image", "video", "audio", "voice", "file"].includes(value);
}

export function isSupportCategory(value: string): value is SupportCategory {
  return ["bug", "complaint", "question", "feedback"].includes(value);
}

// ---------------------------------------------------------------------------
// jsonb payload shapes
// ---------------------------------------------------------------------------

export interface QuestionOption {
  key: string;
  text: string;
}

/** Answer record stored in `exam_attempts.answers` keyed by question id. */
export interface AttemptAnswer {
  selected?: string | null;
  text?: string | null;
  marksAwarded?: number;
  correct?: boolean;
}

/** Configuration snapshot stored in `exam_attempts.config`. */
export interface AttemptConfig {
  topicIds?: string[];
  difficulty?: Difficulty | "all";
  count?: number;
  durationMinutes?: number;
  title?: string;
}

/** A single daily question payload (AI-generated, self-contained). */
export interface DailyQuestionPayload {
  stem: string;
  options?: QuestionOption[];
  answer: string;
  explanation: string;
}

/** One week of an AI study plan. */
export interface StudyPlanWeek {
  week: number;
  focus: string;
  goals: string[];
  days: { day: string; task: string; minutes?: number }[];
}

/** Encrypted attachment metadata stored on `chat_messages.attachment`. */
export interface ChatAttachment {
  /** Storage path inside the private `chat-files` bucket. */
  path: string;
  /** Original file name (shown in the UI). */
  name: string;
  /** MIME type — decides the renderer (image/video/audio/file). */
  mime: string;
  /** Size in bytes of the encrypted blob. */
  size: number;
}

/** Site CMS content (site_settings rows, keyed). */
export interface BrandingSettings {
  site_name: string;
  tagline: string;
  built_by: string;
}

export interface LandingSettings {
  hero_title: string;
  hero_subtitle: string;
  schools_blurb: string;
}

export interface SupportSettings {
  contact_note: string;
}

// ---------------------------------------------------------------------------
// jsonb helpers
// ---------------------------------------------------------------------------

function asRecord(value: unknown): Record<string, unknown> | null {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    return value as Record<string, unknown>;
  }
  return null;
}

/** Widen any JSON-serialisable value for a jsonb insert column. */
export function toJson(value: unknown): Json {
  return value as Json;
}

export function questionOptions(value: unknown): QuestionOption[] {
  if (!Array.isArray(value)) return [];
  const out: QuestionOption[] = [];
  for (const item of value) {
    const record = asRecord(item);
    const key = record?.["key"];
    const text = record?.["text"];
    if (typeof key === "string" && typeof text === "string") {
      out.push({ key, text });
    }
  }
  return out;
}

export function attemptAnswers(value: unknown): Record<string, AttemptAnswer> {
  const record = asRecord(value);
  if (!record) return {};
  const out: Record<string, AttemptAnswer> = {};
  for (const [questionId, raw] of Object.entries(record)) {
    const answer = asRecord(raw);
    if (!answer) continue;
    out[questionId] = {
      selected: typeof answer["selected"] === "string" ? answer["selected"] : null,
      text: typeof answer["text"] === "string" ? answer["text"] : null,
      marksAwarded: typeof answer["marksAwarded"] === "number" ? answer["marksAwarded"] : undefined,
      correct: typeof answer["correct"] === "boolean" ? answer["correct"] : undefined,
    };
  }
  return out;
}

export function attemptConfig(value: unknown): AttemptConfig {
  const record = asRecord(value);
  if (!record) return {};
  const topicIds = Array.isArray(record["topicIds"])
    ? record["topicIds"].filter((id): id is string => typeof id === "string")
    : undefined;
  const difficulty = record["difficulty"];
  return {
    topicIds,
    difficulty:
      difficulty === "easy" ||
      difficulty === "medium" ||
      difficulty === "hard" ||
      difficulty === "all"
        ? difficulty
        : undefined,
    count: typeof record["count"] === "number" ? record["count"] : undefined,
    durationMinutes:
      typeof record["durationMinutes"] === "number" ? record["durationMinutes"] : undefined,
    title: typeof record["title"] === "string" ? record["title"] : undefined,
  };
}

export function dailyQuestionPayload(value: unknown): DailyQuestionPayload | null {
  const record = asRecord(value);
  if (!record) return null;
  const stem = record["stem"];
  const answer = record["answer"];
  if (typeof stem !== "string" || typeof answer !== "string") return null;
  return {
    stem,
    options: questionOptions(record["options"]),
    answer,
    explanation: typeof record["explanation"] === "string" ? record["explanation"] : "",
  };
}

export function studyPlanWeeks(value: unknown): StudyPlanWeek[] {
  if (!Array.isArray(value)) return [];
  const out: StudyPlanWeek[] = [];
  for (const item of value) {
    const record = asRecord(item);
    if (!record) continue;
    const daysRaw = Array.isArray(record["days"]) ? record["days"] : [];
    const days = daysRaw
      .map((day) => asRecord(day))
      .filter((day): day is Record<string, unknown> => day !== null)
      .map((day) => ({
        day: typeof day["day"] === "string" ? day["day"] : "",
        task: typeof day["task"] === "string" ? day["task"] : "",
        minutes: typeof day["minutes"] === "number" ? day["minutes"] : undefined,
      }))
      .filter((day) => day.day.length > 0 && day.task.length > 0);
    out.push({
      week: typeof record["week"] === "number" ? record["week"] : out.length + 1,
      focus: typeof record["focus"] === "string" ? record["focus"] : "",
      goals: Array.isArray(record["goals"])
        ? record["goals"].filter((goal): goal is string => typeof goal === "string")
        : [],
      days,
    });
  }
  return out;
}

export function pushKeys(value: unknown): Record<string, string> {
  const record = asRecord(value);
  if (!record) return {};
  const out: Record<string, string> = {};
  for (const [key, raw] of Object.entries(record)) {
    if (typeof raw === "string") out[key] = raw;
  }
  return out;
}

export function chatAttachment(value: unknown): ChatAttachment | null {
  const record = asRecord(value);
  if (!record) return null;
  const path = record["path"];
  const name = record["name"];
  const mime = record["mime"];
  if (typeof path !== "string" || typeof name !== "string" || typeof mime !== "string") {
    return null;
  }
  return {
    path,
    name,
    mime,
    size: typeof record["size"] === "number" ? record["size"] : 0,
  };
}

function stringField(value: unknown, fallback: string): string {
  return typeof value === "string" && value.length > 0 ? value : fallback;
}

export function brandingSettings(value: unknown): BrandingSettings {
  const record = asRecord(value);
  return {
    site_name: stringField(record?.["site_name"], "BioChem"),
    tagline: stringField(record?.["tagline"], "The complete biochemistry study platform"),
    built_by: stringField(record?.["built_by"], "Aevibron"),
  };
}

export function landingSettings(value: unknown): LandingSettings {
  const record = asRecord(value);
  return {
    hero_title: stringField(record?.["hero_title"], "Master biochemistry. Together."),
    hero_subtitle: stringField(
      record?.["hero_subtitle"],
      "Exam zones, an AI tutor grounded in your course notes, a smart planner, community, and jobs — in one installable app.",
    ),
    schools_blurb: stringField(
      record?.["schools_blurb"],
      "BioChem is live for students at these schools.",
    ),
  };
}

export function supportSettings(value: unknown): SupportSettings {
  const record = asRecord(value);
  return {
    contact_note: stringField(
      record?.["contact_note"],
      "Found a bug, have a complaint, or need help? Send a message to the platform team.",
    ),
  };
}
